void need(bool ok,const std::string& why){if(!ok){throw std::runtime_error(why);}}
InputFrame key(InputAction action=InputAction::Confirm){InputFrame input;input.buttons[static_cast<int>(action)]={true,true,false};return input;}
CombatEntry entry(const CombatContent& c,int map,TilePosition tile){auto e=c.entries.at("defeated-claimed");e.map=map;e.playerTile=tile;e.direction=Direction::Up;e.positions.clear();e.directions.clear();e.pages.clear();e.through.clear();e.session.flags[1]=e.session.flags[18]=true;e.session.flags[13]=e.session.flags[15]=false;e.session.hp=e.session.maxHp=5000;e.session.baseAttack=200;e.session.baseDefense=999;e.session.mainWeapon=19;e.session.inventory[19]=1;e.session.inventory[38]=99;e.session.eventTimer={};return e;}
void finish(CombatScene& scene,bool decline=false){for(int i=0;i<24000&&scene.foreground()!=ForegroundKind::None;++i){if(decline&&scene.inputPromptView().phase!=DialoguePhase::Hidden){scene.update(key(InputAction::Down));}scene.update(key());scene.takePresentation();}need(scene.foreground()==ForegroundKind::None,"Stuck flow map "+std::to_string(scene.mapId()));}
std::optional<Direction> next(const CombatScene& scene,TilePosition target){const auto& w=scene.world();const auto start=w.player().motion.tile();std::queue<TilePosition> q;q.push(start);std::map<std::pair<int,int>,Direction> first;first[{start.x,start.y}]=Direction::Up;
while(!q.empty()){auto pos=q.front();q.pop();auto actor=w.player();actor.motion=CharacterMotion(pos,Direction::Down,32);for(int n=0;n<4;++n){const auto d=static_cast<Direction>(n);const auto tile=adjacentTile(pos,d);const auto k=std::pair{tile.x,tile.y};if(first.contains(k)||!w.canMove(actor,d)){continue;}first[k]=pos==start?d:first.at({pos.x,pos.y});if(tile==target){return first[k];}q.push(tile);}}return {};}
void walk(CombatScene& scene,TilePosition target){const int map=scene.mapId();for(int n=0;n<18000;++n){if(auto requested=scene.takeApplicationRequest()){throw std::runtime_error("Walking interrupted by application mode "+std::to_string(static_cast<int>(*requested))+" on map "+std::to_string(scene.mapId()));}if(scene.mapId()!=map){finish(scene);return;}if(scene.foreground()!=ForegroundKind::None){finish(scene);continue;}if(scene.world().player().motion.moving()){scene.update(n%2==0?key(InputAction::Up):InputFrame{});scene.takePresentation();continue;}if(scene.world().player().motion.tile()==target){scene.update({});return;}InputFrame f;f.movement=next(scene,target);if(n%2==0){f.buttons[static_cast<int>(InputAction::Up)].pressed=true;}scene.update(f);scene.takePresentation();}std::cerr<<"Walk state player="<<scene.world().player().motion.tile().x<<","<<scene.world().player().motion.tile().y<<" HP="<<scene.session().hp()<<" raised="<<scene.raised()<<" ammo="<<scene.session().magazine(19)<<" flags1/18/10/13="<<scene.session().flag(1)<<scene.session().flag(18)<<scene.session().flag(10)<<scene.session().flag(13)<<"\n";for(const auto& enemy:scene.enemyStates()){const auto tile=findCharacter(scene.world(),enemy.id).motion.tile();std::cerr<<enemy.id<<" at "<<tile.x<<","<<tile.y<<" mode "<<static_cast<int>(enemy.mode)<<" source "<<enemy.sourceState<<" damage "<<enemy.damage<<" held "<<enemy.holdsPlayer<<"\n";}throw std::runtime_error("Walk timed out map "+std::to_string(map)+" target "+std::to_string(target.x)+","+std::to_string(target.y));}
void interact(CombatScene& scene,const CombatContent& c,const std::string& id,int destination,bool decline=false){const int map=scene.mapId();std::cout<<"Interact "<<id<<" from "<<map<<"\n"<<std::flush;const auto object=findCharacter(scene.world(),id).motion.tile();const auto* p=c.activeVariant(c.objects.at(id),scene.session());need(p,"Current object page");if(p->definition.layer!=1){walk(scene,object);}else{bool arrived=false;for(int attempt=0;attempt<2400&&!arrived;++attempt){for(int index=0;index<4&&!arrived;++index){const auto player=scene.world().player().motion.tile();int begin=2;for(int side=0;side<4;++side){if(adjacentTile(object,static_cast<Direction>(side))==player){begin=side;break;}}const int n=(index+begin)%4;auto target=adjacentTile(object,static_cast<Direction>(n));if(scene.world().player().motion.tile()!=target&&!next(scene,target)){continue;}walk(scene,target);if(scene.mapId()!=map){need(scene.mapId()==destination,"Contact destination");return;}InputFrame turn;turn.movement=static_cast<Direction>((n+2)%4);turn.buttons[static_cast<int>(InputAction::Cancel)].held=true;scene.update(turn);arrived=true;}if(!arrived){scene.update(attempt%2==0?key(InputAction::Up):InputFrame{});scene.takePresentation();}}need(arrived,"No approach to "+id);}if(scene.mapId()==map){scene.update(key());finish(scene,decline);}need(scene.mapId()==destination,"Wrong destination "+id+" map "+std::to_string(scene.mapId()));}
void menuItem(GameApplication& game,int item){
    game.update(key(InputAction::Cancel));need(game.mode()==ApplicationMode::Equipment,"Map opens real item menu");game.update(key());
    for(int n=0;n<100&&game.menuView().rows.at(game.menuView().selection).id!=item;++n){game.update(key(InputAction::Right));}
    need(game.menuView().rows.at(game.menuView().selection).id==item,"Owned item is selectable");game.update(key());
}
